-- Lot ASSO-4 (15/11/2026), vague 2 : six associations hors protection animale.
-- Décision de Jérémie du 15/11/2026. Repère : asso4_vague2_fiches. Rejouable (ON CONFLICT DO NOTHING).
--
-- Chaque fiche porte un SIREN et un RNA relevés à l'API officielle
-- (recherche-entreprises.api.gouv.fr) le 15/11/2026. Descriptions rédigées par
-- Guardiens à partir des pages publiques de chaque association. Logos servis
-- depuis le site de l'association. Aucune adresse de rue.
INSERT INTO public.animal_associations (slug,name,association_type,city,postal_code,departement_code,species,description,needs,siren,rna,legal_form,website_url,facebook_url,instagram_url,donation_url,volunteer_url,contact_page_url,logo_url,tagline,founded_year,key_figures,needs_details,sources,address,verified_at,consent_status,status,internal_note) VALUES
('restos-du-coeur-rhone','Les Restos du Cœur du Rhône','solidarite','Lyon','69007','69','{}'::text[],'Les Restos du Cœur du Rhône forment l''association départementale du mouvement fondé par Coluche en 1985. Ils accueillent et accompagnent des personnes en difficulté dans 27 centres d''activités du département, un entrepôt et des activités comme le Jardin du Cœur. Les bénévoles tiennent l''accueil et la distribution, accompagnent l''apprentissage du français, conseillent sur le budget, conduisent les véhicules ou gèrent la logistique et l''administratif. Chacun choisit son rythme : quelques heures ponctuelles, comme lors des collectes, ou une présence régulière chaque semaine.',ARRAY['benevoles','dons']::text[],'421804519','W691055508','Association déclarée','https://www.restosducoeur.org/','https://www.facebook.com/restosducoeur/','https://www.instagram.com/restos.du.coeur/','https://www.restosducoeur.org/faire-un-don-financier/','https://www.restosducoeur.org/annonces/','https://www.restosducoeur.org/contact/','https://www.restosducoeur.org/wp-content/uploads/2016/04/logo-restos.svg','Aide alimentaire et accompagnement dans 27 centres du Rhône, avec des missions pour tous les emplois du temps.',NULL,'[{"value": "27", "label": "centres d''activités dans le Rhône", "year": "2026", "source_url": "https://www.jeveuxaider.gouv.fr/missions-benevolat/94766/benevolat-restos-du-coeur-69-76"}, {"value": "Plus de 78 000", "label": "bénévoles dans toute la France", "year": "2026", "source_url": "https://www.restosducoeur.org/devenir-benevole/"}]'::jsonb,'[{"need": "benevoles", "detail": "Les missions du Rhône sont publiées sur la page Trouver ma mission des Restos du Cœur : accueil des personnes, apprentissage du français, conseil budgétaire, chauffeur, logistique, administratif.", "url": "https://www.restosducoeur.org/annonces/"}, {"need": "dons", "detail": "Le don financier se fait en ligne, directement auprès des Restos du Cœur.", "url": "https://www.restosducoeur.org/faire-un-don-financier/"}]'::jsonb,'[{"fact": "SIREN 421 804 519, RNA W691055508, association déclarée, siège à Lyon 7e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=421804519"}, {"fact": "Missions de bénévolat, nombre de centres et chiffres nationaux publiés par l''association", "url": "https://www.restosducoeur.org/devenir-benevole/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 2 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('fne-rhone','France Nature Environnement Rhône (FNE Rhône)','nature','Villeurbanne','69100','69','{}'::text[],'France Nature Environnement Rhône (ex FRAPNA Rhône) agit depuis plus de 50 ans pour protéger et valoriser la nature dans le Rhône et la métropole de Lyon. La fédération réunit des bénévoles, des associations fédérées et une équipe salariée, pour des actions de terrain, d''éducation à la nature et de plaidoyer. Les bénévoles participent à des chantiers écovolontaires (planter une haie, creuser des mares), à des suivis de biodiversité comme celui du blaireau en métropole de Lyon, à l''organisation d''événements publics et aux instances locales où l''association est représentée.',ARRAY['benevoles','dons']::text[],'331172106','W691053905','Association déclarée','https://www.fne-aura.org/rhone/','https://www.facebook.com/fnerhone','https://www.instagram.com/fnerhone/','https://www.fne-aura.org/rhone/faire-un-don/','https://www.fne-aura.org/rhone/','https://www.fne-aura.org/rhone/contact/','https://www.fne-aura.org/uploads/2018/12/logo-header-rhone.png','Chantiers écovolontaires, suivis de biodiversité et événements nature dans le Rhône et la métropole de Lyon.',NULL,'[{"value": "Plus de 50", "label": "ans d''action pour la nature dans le Rhône", "year": "", "source_url": "https://www.helloasso.com/associations/fne-rhone"}]'::jsonb,'[{"need": "benevoles", "detail": "Chantiers écovolontaires, suivis de la biodiversité, organisation d''événements (salon Primevère, rendez-vous de la biodiversité) et contributions aux instances locales. L''agenda et la rubrique Agissez avec nous se trouvent sur son site.", "url": "https://www.fne-aura.org/rhone/"}, {"need": "dons", "detail": "Le don se fait en ligne sur la page de l''association, avec une réduction fiscale de 66 % pour les particuliers.", "url": "https://www.fne-aura.org/rhone/faire-un-don/"}]'::jsonb,'[{"fact": "SIREN 331 172 106, RNA W691053905, association déclarée, siège à Villeurbanne (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=331172106"}, {"fact": "Missions, chantiers et événements publiés par l''association", "url": "https://www.fne-aura.org/rhone/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 2 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('lpo-auvergne-rhone-alpes','LPO Auvergne-Rhône-Alpes','nature','Lyon','69009','69','{}'::text[],'La LPO Auvergne-Rhône-Alpes protège la biodiversité dans toute la région, à travers huit délégations territoriales : Ain, Auvergne, Drôme-Ardèche, Isère, Loire, Rhône, Savoie et Haute-Savoie. Elle propose six façons de s''engager comme bénévole : naturaliste (suivis de terrain, partage d''observations sur Faune-AuRA), secouriste de la nature, sentinelle, éco-volontaire, ambassadeur ou ambassadrice, et spécialiste. Au 31 décembre 2024, elle comptait 13 353 adhérents et 66 groupes locaux ou thématiques de bénévoles.',ARRAY['benevoles','dons']::text[],'301125100','W691061417','Association déclarée','https://auvergne-rhone-alpes.lpo.fr/','https://www.facebook.com/LPO.AuvergneRhoneAlpes','https://www.instagram.com/lpo_aura/','https://auvergne-rhone-alpes.lpo.fr/don/','https://auvergne-rhone-alpes.lpo.fr/s-engager/en-tant-que-citoyen/avec-la-lpo/devenir-benevole/','https://auvergne-rhone-alpes.lpo.fr/contacts-lpo-aura/','https://auvergne-rhone-alpes.lpo.fr/wp-content/uploads/LPO_AuRA.svg','Six façons d''agir pour la biodiversité, du suivi des oiseaux au secours des animaux sauvages, partout dans la région.',NULL,'[{"value": "13 353", "label": "adhérents", "year": "2024", "source_url": "https://auvergne-rhone-alpes.lpo.fr/wp-content/uploads/2025/06/Livret_Tenue-stand.pdf"}, {"value": "66", "label": "groupes locaux ou thématiques de bénévoles", "year": "2024", "source_url": "https://auvergne-rhone-alpes.lpo.fr/wp-content/uploads/2025/06/Livret_Tenue-stand.pdf"}]'::jsonb,'[{"need": "benevoles", "detail": "Le guide du bénévolat présente les six profils et les délégations territoriales. Le contact se fait par la page Devenir bénévole ou par téléphone au 04 37 61 05 06.", "url": "https://auvergne-rhone-alpes.lpo.fr/s-engager/en-tant-que-citoyen/avec-la-lpo/devenir-benevole/"}, {"need": "dons", "detail": "Le don se fait en ligne, sur la page dédiée de l''association.", "url": "https://auvergne-rhone-alpes.lpo.fr/don/"}]'::jsonb,'[{"fact": "SIREN 301 125 100, RNA W691061417, association déclarée, siège à Lyon 9e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=301125100"}, {"fact": "Profils de bénévoles, délégations et chiffres publiés par l''association", "url": "https://auvergne-rhone-alpes.lpo.fr/s-engager/en-tant-que-citoyen/avec-la-lpo/devenir-benevole/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 2 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('mountain-wilderness-france','Mountain Wilderness France','nature','Grenoble','38000','38','{}'::text[],'Mountain Wilderness France, association née en 1988 et basée à Grenoble, défend la montagne par des actions de terrain, des publications expertes et un dialogue avec les acteurs politiques, associatifs et économiques. Les bénévoles rejoignent des groupes de travail thématiques (aménagement, espaces protégés, Silence, montagnes en transition, Changer d''Approche, installations obsolètes, communication) ou un groupe local, organisé par département. Chaque année, des chantiers de démantèlement d''aménagements abandonnés s''ouvrent aux bénévoles : en 2026, trois chantiers nationaux, dans les Hautes-Alpes, en Savoie et dans les Pyrénées-Orientales.',ARRAY['benevoles','dons']::text[],'387488471','W381001634','Association déclarée','https://www.mountainwilderness.fr/','https://www.facebook.com/MountainWildernessFrance/','https://www.instagram.com/mountain_wilderness_france/','https://www.mountainwilderness.fr/je-soutiens','https://www.mountainwilderness.fr/agir-devenir-benevole','https://www.mountainwilderness.fr/nous-contacter','https://www.mountainwilderness.fr/media/images/logos/_AUTOx320_crop_center-center_none/logo@2x.svg','Défense de la montagne, groupes locaux de bénévoles et chantiers de démantèlement d''installations abandonnées.',1988,'[{"value": "30", "label": "délégations départementales", "year": "2026", "source_url": "https://jobs.makesense.org/fr/jobs/mountain-wilderness-chargee-de-mission-vie-associative-contrat-a-duree-determine-a-60-pourcent-sans-terme-precis-kHHUlbNth1CjHZxuu5hz"}, {"value": "3", "label": "chantiers nationaux Installations Obsolètes ouverts aux bénévoles", "year": "2026", "source_url": "https://www.ffrandonnee.fr/s-informer/actualites/les-chantiers-installations-obsoletes-2026-de-mountain-wilderness"}]'::jsonb,'[{"need": "benevoles", "detail": "Groupes de travail thématiques et groupes locaux par département, avec des fiches de missions bénévoles. Les chantiers Installations Obsolètes 2026 sont détaillés sur son site.", "url": "https://www.mountainwilderness.fr/agir-devenir-benevole"}, {"need": "dons", "detail": "Le don et l''adhésion se font en ligne, avec une réduction fiscale.", "url": "https://www.mountainwilderness.fr/je-soutiens"}]'::jsonb,'[{"fact": "SIREN 387 488 471, RNA W381001634, association déclarée, siège à Grenoble (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=387488471"}, {"fact": "Groupes de travail, groupes locaux et chantiers publiés par l''association", "url": "https://www.mountainwilderness.fr/agir-devenir-benevole"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 2 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('concordia-chantiers-benevoles','Concordia','chantier','Paris','75005','75','{}'::text[],'Concordia est une association de jeunesse et d''éducation populaire, créée en 1950, qui organise des chantiers internationaux de bénévoles. Des participants venus de pays différents réalisent ensemble, pendant deux à trois semaines, un projet utile à un territoire : patrimoine, environnement, solidarité. Chaque année, plus de 100 chantiers ont lieu en France et plus de 800 bénévoles étrangers sont accueillis. L''association, présente en Rhône-Alpes par sa délégation de Lyon, propose aussi l''animation de chantier, le Service Civique et le Corps européen de solidarité.',ARRAY['participants','benevoles']::text[],'993697143','W751280964','Association déclarée','https://www.concordia.fr/','https://www.facebook.com/AssociationConcordia/','https://www.instagram.com/concordiafrance',NULL,'https://www.concordia.fr/sengager/chantier-international/','https://www.concordia.fr/contact/','https://www.concordia.fr/wp-content/uploads/2022/02/logo-couleur-sans-trait-blanc.png','Chantiers internationaux de bénévoles en France et dans le monde, ouverts à tous, avec une délégation à Lyon.',1950,'[{"value": "Plus de 100", "label": "chantiers chaque année en France", "year": "2026", "source_url": "https://www.concordia.fr/"}, {"value": "Plus de 800", "label": "bénévoles étrangers accueillis chaque année en France", "year": "2026", "source_url": "https://www.concordia.fr/"}]'::jsonb,'[{"need": "participants", "detail": "Le catalogue des chantiers internationaux se consulte sur le site, avec une inscription en ligne. Les projets sont ouverts à tous et à toutes.", "url": "https://www.concordia.fr/sengager/chantier-international/"}, {"need": "benevoles", "detail": "Des missions de bénévolat au sein de l''association et l''animation de chantier sont présentées sur sa rubrique S''engager.", "url": "https://www.concordia.fr/sengager/etre-benevole-au-sein-de-concordia/"}]'::jsonb,'[{"fact": "SIREN 993 697 143, RNA W751280964, association déclarée, siège à Paris 5e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=993697143"}, {"fact": "Chantiers, chiffres et rubrique S''engager publiés par l''association", "url": "https://www.concordia.fr/"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 2 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.'),
('rempart-chantiers-patrimoine','REMPART','chantier','Paris','75004','75','{}'::text[],'REMPART, créée en 1966, fait du patrimoine un trait d''union entre les personnes. Le réseau organise des chantiers de bénévoles pour restaurer et faire vivre châteaux, chapelles, villages et sites archéologiques, en France et à l''étranger, avec des spécialistes qui transmettent leur savoir-faire. Les chantiers accueillent tous les âges et tous les niveaux de compétence : enfants, adolescents, familles et adultes. En Auvergne-Rhône-Alpes, l''union régionale réunit des associations locales, dont celles du château d''Urfé et de la cure de Biviers.',ARRAY['participants','benevoles']::text[],'784672263','W751009948','Association déclarée','https://www.rempart.com/','https://www.facebook.com/REMPARTasso','https://www.instagram.com/rempart_asso/','https://www.rempart.com/don','https://www.rempart.com/fr/trouver-un-chantier','https://www.rempart.com/fr/contact','https://www.rempart.com/images/logos/logo.png','Chantiers de bénévoles pour restaurer le patrimoine, ouverts à tous les âges, partout en France.',1966,'[{"value": "1966", "label": "année de création de l''association", "year": "", "source_url": "https://www.rempart.com/"}, {"value": "10 000", "label": "citoyens engagés dans un projet local au sein du réseau", "year": "2021", "source_url": "https://www.petale07.org/wp-content/uploads/2022/05/Concertation-bilan-2021_Jeudi-09.12.2021_compressed.pdf"}]'::jsonb,'[{"need": "participants", "detail": "Les chantiers 2026 se trouvent sur la page Trouver un chantier, avec les modalités d''inscription et les aides au départ.", "url": "https://www.rempart.com/fr/trouver-un-chantier"}, {"need": "dons", "detail": "Le don se fait en ligne, directement auprès de l''association.", "url": "https://www.rempart.com/don"}]'::jsonb,'[{"fact": "SIREN 784 672 263, RNA W751009948, association déclarée, siège à Paris 4e (vérifié à l''API officielle le 15/11/2026)", "url": "https://recherche-entreprises.api.gouv.fr/search?q=784672263"}, {"fact": "Chantiers de bénévoles, accueil de tous les âges et réseau régional publiés par l''association", "url": "https://www.rempart.com/fr/trouver-un-chantier/le-chantier-de-benevoles"}]'::jsonb,NULL,'2026-11-15','pending','published','ASSO-4 vague 2 : SIREN et RNA vérifiés à l''API officielle le 15/11/2026, descriptions rédigées par Guardiens, logo servi depuis le site de l''association.')
